using Microsoft.AspNetCore.Mvc; using TuneHire.Api.Data; using TuneHire.Api.Models; namespace TuneHire.Api.Controllers { [ApiController] [Route("api/[controller]")] public class BookingsController : ControllerBase { private readonly AppDbContext _db; public BookingsController(AppDbContext db) { _db = db; } [HttpPost] public IActionResult Create(Booking b) { b.Status = "Pending"; _db.Bookings.Add(b); _db.SaveChanges(); return CreatedAtAction(nameof(GetById), new { id = b.Id }, b); } [HttpGet("user/{userId}")] public IActionResult ForUser(int userId) => Ok(_db.Bookings.Where(x=>x.UserId==userId).ToList()); [HttpGet("{id}")] public IActionResult GetById(int id) => Ok(_db.Bookings.Find(id)); } }